  @JavascriptInterface public void screenOption(boolean enabled){runOnUiThread(()->{if(!enabled){LedgerDb.prefs(MainActivity.this).edit().putBoolean("screen_capture",false).apply();refresh();return;}showAppDialog("启用页面识别？","按自动记账中的来源设置检查付款成功页面，可限制为所选应用。普通页面综合校验成功状态、实付金额、优惠和商户；无明确状态但具备完整付款凭证的记录交待确认；拒绝聊天、输入页、历史订单及矛盾金额。微信和支付宝另有支付、转账、红包专用规则。微信支付服务页、支付宝支付消息按屏幕内同卡位置读取，也包含应用标为不可见的正文。金额候选在内存中最多3分钟，结合您自己的发送/领取动作和成功结果判断。仅开启耗电诊断且允许保留原文时，节点诊断每个24小时采样周期最多保存8份本机样本，可能含交易正文；满24小时后由后台任务或打开应用时清理，系统可能延迟。视觉辅助可学习成功标题。不录屏、不上传、不自动点击，不采集密码、验证码或聊天输入。缺证据和旧详情待核对，仍可能漏记。需手动授权无障碍。","同意并授权","暂不开启",false,()->{LedgerDb.prefs(MainActivity.this).edit().putBoolean("screen_capture",true).apply();startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));refresh();},()->refresh());});}
