  @JavascriptInterface public String save(String json){try{JSONObject o=new JSONObject(json);String kind=o.getString("kind"),category=o.getString("category"),merchant=o.getString("merchant"),source=o.optString("source","manual");long cents=o.getLong("cents"),time=o.getLong("time"),id=o.optLong("_id",0);
   if(!Arrays.asList("expense","income","refund").contains(kind)||!Arrays.asList(LedgerDb.CATEGORIES).contains(category)||merchant.length()>100||cents<=0||cents>99999999999L||time<0||time>4102444800000L||(source.isEmpty()||source.length()>255))return "输入不合法，请核对金额、日期和分类";
   db.save(id,time,source,kind,cents,merchant.trim(),category,"confirmed");MainActivity.this.refresh();return "";
  }catch(Exception e){return "保存失败，请核对输入";}}
