  @JavascriptInterface public void clearRaw(){runOnUiThread(()->showAppDialog("清除交易原文？","删除账目原文和诊断样本，无法撤销。金额、商户、去重字段与统计保留；已导出的文件不变。","清除","取消",true,()->{toast("正在清除原文…");dataWorker.execute(()->{try{db.clearRaw();ServiceNodeDiagnostic.clear(MainActivity.this);refresh();toast("原文与诊断样本已清除，账目保留");}catch(Exception e){toast("清除失败，请重试");}});},null));}
  @JavascriptInterface public void clearAll(){runOnUiThread(()->showAppDialog("清空全部账本？","删除全部流水、待确认、修改历史与去重记录，无法撤销，请先备份。预算、提醒、设置和导出文件保留。","全部删除","取消",true,()->{toast("正在清空账本…");dataWorker.execute(()->{try{db.clearAll();refresh();toast("账本已清空");}catch(Exception e){toast("清空失败，请重试");}});},null));}
  @JavascriptInterface public void exportFile(String type){runOnUiThread(()->{if(!type.equals("csv")&&!LedgerDb.prefs(MainActivity.this).getBoolean("backup_ack",false)){showBackupCode();return;}pendingExport=type.equals("csv")?"csv":"html";Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(pendingExport.equals("csv")?"text/csv":"text/html");i.putExtra(Intent.EXTRA_TITLE,"轻记-"+new SimpleDateFormat("yyyyMMdd-HHmm",Locale.CHINA).format(new Date())+"."+pendingExport);try{startActivityForResult(i,EXPORT);}catch(Exception e){toast("未找到文件保存器");}});}
